}
dir$m55.prototype.formFieldValueChange = function (o, cF, v) {
  var p = this._dir;
  switch (cF){
&VoucherExRateValid01;
    case 'ma_gd':
      dir$m55HiddenColumnByTran(p);
      break;
    case 'ma_ngv':
      dir$m55HiddenColumnByType(p);
      break;
    case 'ty_gia':
      p.calcExpressionAll(0, '!ty_gia');
      break;
    case 'ma_kh':
      p.request('Customer', '', ['ma_kh', 'ngay_ct', 'ma_nt']);
      break;
    default:
      break;
  }
}
&VoucherExRateValid02;
dir$m55.prototype.gridDetailActionChange = function(gindex, action, r){
  if(gindex > 0) return true;

  var p = this._dir;
  if (action == 'AfterDeleteRow' || action == 'AfterAppendGrid') dir$m55DisabledMasterField(p, p.grid(gindex));
  return true;
}
function dir$m55DisabledMasterField(p, g){
  var dt = g.data, rows = dt.findRow("[ma_vt].trim() != ''"), dis = rows.length > 0;
  p.setDisabled('unit_id', dis);
  p.setInactive('unit_id', true);
  p.setDisabled('ma_ngv', dis);
  if (p.options._sale_lock_master == 1) 
    p.setDisabled(['ma_kh', 'ngay_ct', 'ma_nt'], dis);
  else {
    rows = dt.findRow("[ma_vt].trim() != '' && [id_px] > 0"), dis = rows.length > 0;
    p.setDisabled('ma_kh', dis);
  }
}
function dir$m55HiddenColumnByType(p){
  var v = p.valForm('ma_ngv'), nt = p.valForm('ma_nt'), bc = p.options.struct.baseCurrency;
  p.setColumnHidden(0, ['sl_px'], v == 3);
  p.setColumnHidden(0, ['line_px', 'so_ct_px'], v == 3);
  p.setColumnHidden(0, ['gia', 'tien'], nt == bc);
  p.setInvisible(['t_tien'], nt == bc);
}
function dir$m55HiddenColumnByTran(p){

}
function dir$m55DisabledStatusByAction(p){
  var o = p.jObject('status');
  if (p.options.action != 'VIEW') o.find("[value=6],[value=7],[value=9]").remove();
}







